else_if_give_back.source:
-- Every branch gives back, so nothing follows the chain.
task sign(n: int) -> int {
    if n > 0 {
        give back 1
    } else if n < 0 {
        give back 2
    } else {
        give back 3
    }
}

task main() -> int {
    give back sign(5)
}

else_if_trailing.source:
-- The same decision, with the last case after the chain.
task sign(n: int) -> int {
    if n > 0 {
        give back 1
    } else if n < 0 {
        give back 2
    }
    give back 3
}

task main() -> int {
    give back sign(5) * 100 + sign(0 - 5) * 10 + sign(0)
}

