int_and_num.source:
task main() -> int {
    pilot a = 7
    pilot b = 2
    pilot thrust: num = 2.5

    -- 7 / 2 is 3 and 7 % 2 is 1, so this part is 31.
    pilot whole = a / b * 10 + a % b

    if thrust * 2.0 > 4.9 { give back whole + 5 }
    give back whole
}

loops.source:
-- Three of V3's loops, with break and continue, on V4.
task main() -> int {
    pilot total = 0

    repeat 4 times { total += 10 }              -- 40

    pilot n = 0
    repeat until n >= 6 {
        n += 1
        if n == 2 { continue }                  -- skips 2
        if n == 5 { break }                     -- stops before 5
        total += n                              -- adds 1, 3, 4
    }

    pilot drills = 0
    training arc until drills >= 3 max 10 sessions { drills += 1 }

    give back total + drills                    -- 40 + 8 + 3
}

