num_into_int.source:
-- V3 refuses all three of these. This V4 commit drops the fraction
-- and says nothing.
task whole(n: int) -> int {
    give back n
}

task main() -> int {
    pilot sorties: int = 2.5                    -- becomes 2
    pilot fuel = 10
    fuel = 7.9                                  -- becomes 7
    give back sorties * 10 + fuel + whole(3.99) -- 20 + 7 + 3
}

numeric_types.source:
-- Four of the specification's extra types. Three have a literal suffix;
-- a char is written in single quotes.
task main() -> int {
    pilot count: uint = 42u            -- unsigned 64-bit
    pilot more: uint = count + 8u

    pilot small: tiny = 7t             -- one byte
    pilot next: tiny = small + 1t

    pilot ratio: float = 3.14f         -- the explicit 64-bit float
    pilot initial: char = 'a'          -- one character, in single quotes

    pilot passed = 0
    if more == 50u { passed += 1 }
    if next == 8t { passed += 1 }
    if ratio > 3.0f { passed += 1 }
    give back passed
}

overflow_wraps.source:
-- Past the largest int the value wraps around, as it does in V3.
task main() -> int {
    pilot largest: int = 9223372036854775807
    pilot next = largest + 1
    if next < 0 { give back 1 }
    give back 0
}

