training_arc_cap.source:
-- The condition here needs eleven passes; the cap allows three.
-- V3 stops at 3. This V4 snapshot checks the cap's type but does not
-- enforce it, so the loop runs until the condition is true.
task main() -> int {
    pilot drills = 0
    training arc until drills > 10 max 3 sessions {
        drills += 1
    }
    give back drills
}

truth_literal_case.source:
-- A truth literal in any capitalisation is still a truth literal in V4,
-- and it means what it says. Each test that passes adds to the exit code.
task main() -> int {
    pilot code = 0
    if TRUE { code += 1 }
    if Yes { code += 2 }
    if not FALSE { code += 4 }
    give back code
}

